// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"tr","terms":[["short-selling","Açığa satış (Short selling)","Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir.","derivatives",1],["public-key","Açık anahtar (public key)","Açık anahtar, özel anahtardan matematiksel olarak türetilen, imzaların doğrulanmasına yarayan ve genellikle cüzdan adresinin üretilmesinde kullanılan paylaşılabilir anahtardır.","wallets-security",1],["open-interest","Açık pozisyon miktarı (Open interest)","Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir.","derivatives",1],["address-poisoning","Adres zehirleme (address poisoning)","Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır.","wallets-security",1],["airdrop","Airdrop","Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır.","basics",1],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır.","basics",1],["active-addresses","Aktif adres sayısı (active addresses)","Aktif adres sayısı, belirli bir sürede, genellikle bir günde, bir blockchain'de işlem gönderen veya alan benzersiz adreslerin sayısıdır ve ağ kullanımını ölçmek için kullanılır.","onchain",1],["algorithmic-stablecoin","Algoritmik stablecoin","Algoritmik stablecoin, fiyatını tam rezerv yerine arz-talebi otomatik ayarlayan kurallar ve çoğu zaman ikinci bir token ile 1 dolarda tutmaya çalışan stablecoin türüdür.","stablecoins",1],["bid-ask-spread","Alış-satış makası (spread)","Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir.","trading",1],["sub-account","Alt hesap (sub-account)","Alt hesap, ana borsa hesabınıza bağlı, ayrı bakiyesi, ayrı API anahtarları ve ayrı risk ayarları olan ek bir hesaptır; stratejileri ve riskleri birbirinden ayırmak için kullanılır.","exchange-features",1],["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar.","basics",1],["aml","AML (kara para aklamayı önleme)","AML (Anti-Money Laundering), suç gelirlerinin finansal sistemde temiz para gibi gösterilmesini önlemeye yönelik yasal kurallar, kontroller ve izleme süreçlerinin bütünüdür.","regulation",1],["apr-vs-apy","APR ve APY farkı","APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir.","defi",1],["arbitrage","Arbitraj (Arbitrage)","Arbitraj, aynı varlığın farklı piyasalardaki fiyat farkından yararlanmak için ucuz olduğu yerden alıp pahalı olduğu yerde satma işlemidir.","trading",1],["bear-market","Ayı piyasası (bear market)","Ayı piyasası (bear market), fiyatların uzun bir dönem boyunca genel olarak düştüğü, yatırımcı karamsarlığının ve düşük ilginin hakim olduğu piyasa evresidir.","basics",1],["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar.","derivatives",1],["whale","Balina (Whale)","Balina, tek başına piyasayı etkileyebilecek kadar büyük miktarda kripto varlık tutan kişi, şirket veya kurumdur.","trading",1],["initial-margin","Başlangıç teminatı (Initial margin)","Başlangıç teminatı, kaldıraçlı bir pozisyonu açabilmek için hesabınızda bulunması ve pozisyona bağlanması gereken asgari teminat tutarıdır.","derivatives",1],["unified-trading-account","Birleşik işlem hesabı (UTA)","Birleşik işlem hesabı (UTA), spot, vadeli ve opsiyon gibi farklı ürünleri tek bir hesapta toplayıp tüm bakiyenizi ortak teminat olarak kullanmanıza izin veren borsa hesap yapısıdır.","exchange-features",1],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır.","basics",1],["bitcoin-halving","Bitcoin halving (yarılanma)","Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır.","basics",1],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir.","basics",1],["block-explorer","Blok gezgini (block explorer)","Blok gezgini, bir blockchain'deki işlemleri, adresleri ve blokları herkesin arama yapıp görebileceği şekilde listeleyen web tabanlı bir araçtır.","onchain",1],["block-confirmations","Blok onayı (confirmation)","Blok onayı, bir işlemin bir bloğa eklenmesinden sonra üzerine eklenen her yeni bloğu ifade eder; onay sayısı arttıkça işlemin geri alınması pratikte imkânsız hâle gelir.","wallets-security",1],["oracle","Blokzincir oracle'ı (kâhin)","Blokzincir oracle'ı, fiyatlar veya hava durumu gibi blokzincir dışındaki verileri akıllı sözleşmelere güvenilir biçimde taşıyan hizmettir; DeFi protokolleri teminat ve tasfiye hesaplarında bu verilere dayanır.","defi",1],["bull-market","Boğa piyasası (bull market)","Boğa piyasası (bull market), fiyatların uzun bir dönem boyunca genel olarak yükseldiği, yatırımcı iyimserliğinin ve işlem hacminin arttığı piyasa evresidir.","basics",1],["exchange-netflow","Borsa giriş ve çıkışları (netflow)","Borsa giriş ve çıkışları, belirli bir sürede borsa cüzdanlarına yatırılan ve oradan çekilen coin miktarını, netflow ise bu ikisi arasındaki farkı gösteren zincir üstü göstergedir.","onchain",1],["geo-restrictions","Bölge kısıtlamaları (geo-restrictions)","Bölge kısıtlamaları, bir kripto borsasının veya ürünün yasal ve düzenleyici nedenlerle belirli ülkelerde yaşayan kullanıcılara hizmet vermemesi ya da bazı özellikleri kapatmasıdır.","regulation",1],["cbdc","CBDC (merkez bankası dijital parası)","CBDC, bir ülkenin merkez bankasının doğrudan çıkardığı ve resmi paranın dijital hâli olan, yasal ödeme aracı statüsündeki dijital para birimidir.","stablecoins",1],["coin-margined-futures","Coin teminatlı vadeli kontrat (Coin-margined futures)","Coin teminatlı vadeli kontrat, teminatın ve kâr-zararın USDT yerine BTC veya ETH gibi dayanak coinin kendisiyle hesaplandığı ters (inverse) vadeli işlem sözleşmesidir.","derivatives",1],["coin-vs-token","Coin ve token farkı","Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi).","basics",1],["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür.","wallets-security",1],["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur.","derivatives",1],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır.","wallets-security",1],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir.","exchange-features",1],["dual-investment","Çift yatırım (dual investment)","Çift yatırım (dual investment), belirlenen vade sonunda fiyatın hedef fiyata göre konumuna bağlı olarak paranızı ya ana coin ya da stablecoin olarak, her iki durumda da ek getiriyle geri aldığınız opsiyon tabanlı bir üründür.","exchange-features",1],["multisig-wallet","Çoklu imza cüzdanı (multisig)","Çoklu imza (multisig) cüzdanı, bir işlemin gerçekleşmesi için birden fazla özel anahtarın onayını gerektiren, örneğin 3 anahtardan 2'sinin imzasını isteyen kripto cüzdanıdır.","wallets-security",1],["dao","DAO (merkeziyetsiz otonom organizasyon)","DAO, kurallarının akıllı sözleşmelerle tanımlandığı ve kararlarının genellikle yönetişim token'ı sahiplerinin oylarıyla alındığı, yöneticisi tek bir şirket olmayan internet tabanlı bir organizasyondur.","defi",1],["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir.","defi",1],["defi-lending","DeFi borç verme (DeFi lending)","DeFi borç verme, kullanıcıların kripto varlıklarını akıllı sözleşme havuzlarına yatırarak faiz kazandığı, başkalarının da bu havuzlardan teminat göstererek borç aldığı merkeziyetsiz kredi sistemidir.","defi",1],["delisting","Delisting (borsadan çıkarma)","Delisting, bir borsanın bir token'ın veya işlem çiftinin alım satımını durdurup ardından yatırma ve çekim hizmetlerini de kapatarak o varlığı platformdan kaldırmasıdır.","exchange-features",1],["demo-trading","Demo işlem (deneme hesabı)","Demo işlem, gerçek para kullanmadan, borsanın verdiği sanal bakiyeyle gerçek piyasa fiyatları üzerinde alım satım ve vadeli işlem pratiği yapmanızı sağlayan deneme modudur.","exchange-features",1],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez.","stablecoins",1],["support-and-resistance","Destek ve direnç (Support and resistance)","Destek ve direnç, grafikte fiyatın daha önce düşüşünün (destek) veya yükselişinin (direnç) durduğu ve alıcılarla satıcıların yoğunlaştığı fiyat bölgeleridir.","trading",1],["circulating-supply","Dolaşımdaki arz (circulating supply)","Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır.","basics",1],["pig-butchering-scam","Domuz kasaplığı dolandırıcılığı (pig butchering)","Domuz kasaplığı dolandırıcılığı, dolandırıcının haftalarca güven veya romantik ilişki kurduktan sonra kurbanı sahte bir kripto yatırım platformuna para yatırmaya ikna ettiği ve sonunda tüm parayı aldığı uzun soluklu bir dolandırıcılıktır.","wallets-security",1],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır.","wallets-security",1],["instant-convert","Dönüştür (anında çevirme)","Dönüştür (Convert), borsada emir defteriyle uğraşmadan bir coin'i başka bir coin'e tek ekranda, size önceden gösterilen sabit bir kur üzerinden anında çevirmenizi sağlayan özelliktir.","exchange-features",1],["node","Düğüm (node)","Düğüm (node), bir blockchain ağına bağlanan, işlemleri ve blokları doğrulayan, yayan ve çoğu zaman zincirin bir kopyasını saklayan bilgisayar veya yazılımdır.","onchain",1],["dollar-cost-averaging","Düzenli alım stratejisi (DCA)","DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir.","trading",1],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür.","wallets-security",1],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir.","trading",1],["time-in-force","Emir geçerlilik süresi (GTC, IOC, FOK)","Emir geçerlilik süresi (time in force), bir emrin ne kadar süre aktif kalacağını ve dolmayan kısmına ne olacağını belirleyen ayardır; en yaygın seçenekler GTC, IOC ve FOK'tur.","trading",1],["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır.","derivatives",1],["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır.","basics",1],["fiat-on-ramp","Fiat giriş kanalı (fiat on-ramp)","Fiat giriş kanalı (on-ramp), Türk lirası, dolar veya euro gibi geleneksel parayı kripto varlığa çevirmenizi sağlayan yol ya da hizmettir; banka havalesi, kartla alım ve P2P bunun örnekleridir.","regulation",1],["flash-loan","Flaş kredi (flash loan)","Flaş kredi, teminat gerektirmeyen ama aynı blokzincir işlemi içinde alınıp geri ödenmesi zorunlu olan bir DeFi borcudur; geri ödenmezse tüm işlem iptal edilir.","defi",1],["fomo","FOMO (fırsatı kaçırma korkusu)","FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir.","basics",1],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır.","derivatives",1],["funding-rate-arbitrage","Fonlama oranı arbitrajı (Funding rate arbitrage)","Fonlama oranı arbitrajı, spot piyasada bir coin alıp aynı miktarda perpetual short açarak fiyat riskini nötrlediğiniz ve pozitif fonlama ödemelerini topladığınız stratejidir.","derivatives",1],["fud","FUD (korku, belirsizlik ve şüphe)","FUD (fear, uncertainty and doubt), bir kripto para veya proje hakkında korku, belirsizlik ve şüphe yaratan haberler, söylentiler ya da yorumlar için kullanılan bir terimdir.","basics",1],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır.","basics",1],["impermanent-loss","Geçici kayıp (impermanent loss)","Geçici kayıp, bir likidite havuzuna yatırdığınız token'ların fiyat oranı değiştiğinde, pozisyonunuzun değerinin aynı token'ları cüzdanda tutmaya göre daha düşük kalması durumudur.","defi",1],["real-world-assets","Gerçek dünya varlıkları (RWA)","Gerçek dünya varlıkları (RWA), devlet tahvilleri, altın, gayrimenkul, krediler veya hisseler gibi blockchain dışındaki varlıkların zincir üstünde token olarak temsil edilmesidir.","tokenized-assets",1],["unrealized-pnl","Gerçekleşmemiş kâr/zarar (Unrealized PnL)","Gerçekleşmemiş kâr/zarar (unrealized PnL), açık bir pozisyonun mevcut fiyata göre hesaplanan ama pozisyon kapatılmadığı için henüz kesinleşmemiş kâr veya zararıdır.","derivatives",1],["yield-farming","Getiri çiftçiliği (yield farming)","Getiri çiftçiliği (yield farming), kripto varlıkları DeFi protokollerine likidite, borç veya stake olarak yatırıp ücret, faiz ve ödül token'larıyla getiri elde etmeye çalışma stratejisidir.","defi",1],["grid-trading-bot","Grid trading botu (ızgara botu)","Grid trading botu, belirlediğiniz fiyat aralığını eşit basamaklara bölüp her basamakta otomatik alım ve satım emirleri vererek yatay piyasadaki dalgalanmalardan küçük kârlar toplayan bottur.","exchange-features",1],["hash-rate","Hash oranı (hash rate)","Hash oranı, iş ispatı (proof of work) kullanan bir ağda madencilerin saniyede yaptığı toplam hash hesaplama sayısıdır ve ağın işlem gücünü ve güvenliğini gösterir.","onchain",1],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir.","derivatives",1],["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır.","basics",1],["stock-perpetuals","Hisse senedi sürekli vadelileri (stock perpetuals)","Hisse senedi sürekli vadelileri, bir hissenin fiyatını takip eden, vadesi olmayan ve genellikle USDT ile teminatlandırılan, kaldıraçla long veya short açılabilen kripto borsası türev kontratlarıdır.","tokenized-assets",1],["hodl","HODL","HODL, kısa vadeli fiyat dalgalanmalarına rağmen kripto paraları satmadan uzun süre elde tutma stratejisini ifade eden, 2013'teki bir forum yazısındaki yazım hatasından doğmuş bir terimdir.","basics",1],["two-factor-authentication","İki faktörlü doğrulama (2FA)","İki faktörlü doğrulama (2FA), hesabınıza girişte veya çekimde şifrenin yanında ikinci bir kanıt, örneğin bir doğrulama uygulamasından gelen 6 haneli kod istenmesini sağlayan güvenlik katmanıdır.","wallets-security",1],["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır.","basics",1],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır.","derivatives",1],["trading-pair","İşlem çifti (parite)","İşlem çifti (parite), bir borsada birbirine karşı alınıp satılan iki varlığı gösterir; BTC/USDT paritesinde BTC alınan veya satılan varlık, USDT ise fiyatın ifade edildiği birimdir.","trading",1],["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır.","trading",1],["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar.","wallets-security",1],["trailing-stop","İz süren stop (trailing stop)","İz süren stop (trailing stop), fiyat lehinize hareket ettikçe tetik seviyesini otomatik olarak belirli bir yüzde veya tutar kadar geriden takip ettiren, fiyat geri döndüğünde ise pozisyonu kapatan bir emirdir.","trading",1],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur.","derivatives",1],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır.","derivatives",1],["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir.","trading",1],["layer-1","Katman 1 (Layer 1, L1)","Katman 1 (Layer 1, L1), işlemleri kendi başına doğrulayıp kesinleştiren, kendi uzlaşma mekanizmasına ve yerel coinine sahip temel blockchain ağıdır; Bitcoin, Ethereum ve Solana buna örnektir.","basics",1],["layer-2","Katman 2 (Layer 2, L2)","Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır.","basics",1],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar.","trading",1],["total-value-locked","Kilitli toplam değer (TVL)","Kilitli toplam değer (TVL), bir DeFi protokolünün veya blokzincirin akıllı sözleşmelerinde yatırılmış olarak duran tüm varlıkların güncel piyasa değeridir.","defi",1],["copy-trading","Kopya işlem (copy trading)","Kopya işlem (copy trading), seçtiğiniz bir trader'ın açtığı ve kapattığı pozisyonların, belirlediğiniz tutar ve oranla sizin hesabınızda otomatik olarak tekrarlanmasıdır.","exchange-features",1],["fear-and-greed-index","Korku ve Açgözlülük Endeksi (Fear and Greed Index)","Korku ve Açgözlülük Endeksi, kripto piyasasındaki genel duyguyu 0 ile 100 arasında tek bir sayıyla gösteren; 0 aşırı korkuyu, 100 aşırı açgözlülüğü ifade eden bir göstergedir.","onchain",1],["crypto-wallet","Kripto cüzdan (Crypto wallet)","Kripto cüzdan, kripto varlıklarınıza erişmenizi sağlayan özel anahtarları saklayan ve bu anahtarlarla işlem imzalamanıza imkân veren yazılım veya donanımdır.","wallets-security",1],["crypto-earn","Kripto kazanç ürünleri (Earn)","Kripto kazanç (Earn) ürünleri, borsaların kullanıcıların coin'lerini esnek veya vadeli olarak yatırıp karşılığında faiz benzeri getiri almasını sağlayan birikim ve getiri ürünleridir.","exchange-features",1],["mining","Kripto madenciliği (mining)","Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir.","basics",1],["options","Kripto opsiyon (Crypto options)","Kripto opsiyon, sahibine belirli bir kripto varlığı belirli bir fiyattan belirli bir tarihte veya o tarihe kadar alma (call) ya da satma (put) hakkı veren, ama yükümlülük getirmeyen türev sözleşmedir.","derivatives",1],["cryptocurrency","Kripto para (cryptocurrency)","Kripto para, bir merkez bankası ya da şirket yerine bir blockchain ağı tarafından kaydı tutulan, kriptografiyle korunan ve internet üzerinden doğrudan kişiden kişiye gönderilebilen dijital bir varlıktır.","basics",1],["crypto-backed-stablecoin","Kripto teminatlı stablecoin","Kripto teminatlı stablecoin, dolar rezervi yerine akıllı sözleşmede kilitlenen ETH gibi kripto varlıklarla, genellikle değerinden fazla teminatla desteklenen stablecoin'dir.","stablecoins",1],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir.","wallets-security",1],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir.","regulation",1],["no-kyc-exchange","KYC'siz borsa (no-KYC exchange)","KYC'siz borsa, hesap açmak ve belirli limitlere kadar işlem yapmak için kimlik doğrulaması istemeyen merkezi veya merkeziyetsiz kripto alım satım platformudur.","regulation",1],["launchpad","Launchpad (token satışı)","Launchpad, bir borsanın veya platformun yeni bir projenin token'larını listelemeden önce kullanıcılara belirli bir fiyattan sattığı token satış platformudur; borsa üzerinden yapılan satışa IEO da denir.","exchange-features",1],["launchpool","Launchpool","Launchpool, borsanın belirli coin'leri veya stablecoin'leri havuzda kilitleyen kullanıcılara, yeni listelenecek bir projenin token'larını belirli bir süre boyunca ücretsiz dağıttığı programdır.","exchange-features",1],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır.","derivatives",1],["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir.","derivatives",1],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür.","trading",1],["liquidity-pool","Likidite havuzu (liquidity pool)","Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur.","defi",1],["liquid-staking","Likit staking (liquid staking)","Likit staking, coinlerinizi stake ederken karşılığında stake edilen pozisyonu temsil eden ve alınıp satılabilen bir token (örneğin stETH) almanızı sağlayan staking yöntemidir.","defi",1],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir.","trading",1],["long-and-short","Long ve short pozisyon","Long pozisyon, fiyatın yükselmesinden kazanç sağlamak için açılan alış pozisyonudur; short pozisyon ise fiyatın düşmesinden kazanç sağlamak için açılan satış pozisyonudur.","derivatives",1],["long-short-ratio","Long/short oranı (Long/short ratio)","Long/short oranı, bir vadeli işlem piyasasında long pozisyon tutan hesapların veya pozisyonların short tarafına oranını gösteren bir piyasa duyarlılığı göstergesidir.","derivatives",1],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır.","trading",1],["margin-trading","Marjin ticareti (Margin trading)","Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür.","derivatives",1],["memecoin","Memecoin","Memecoin, bir internet şakası, hayvan figürü veya popüler kültür öğesinden ilham alan, değeri büyük ölçüde topluluk ilgisine ve spekülasyona dayanan bir kripto paradır; Dogecoin ve Shiba Inu en bilinen örneklerdir.","basics",1],["memo-tag","Memo / hedef etiketi (destination tag)","Memo veya hedef etiketi, bazı coinlerde borsaya yapılan bir yatırmanın hangi kullanıcıya ait olduğunu belirlemek için adresin yanında gönderilen ek koddur.","wallets-security",1],["mempool","Mempool (bekleyen işlem havuzu)","Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır.","onchain",1],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur.","trading",1],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır.","defi",1],["mev","MEV (maksimum çıkarılabilir değer)","MEV (maksimum çıkarılabilir değer), blok üreticilerinin ve botların bir bloktaki işlemlerin sırasını belirleyerek, ekleyerek veya çıkararak elde edebildiği ek kârdır.","defi",1],["mica","MiCA (AB Kripto Varlık Piyasaları Tüzüğü)","MiCA (Markets in Crypto-Assets), Avrupa Birliği'nde kripto varlık ihraççıları, stablecoin'ler ve kripto hizmet sağlayıcıları için ortak kurallar koyan kapsamlı AB düzenlemesidir.","regulation",1],["candlestick-chart","Mum grafiği (Candlestick chart)","Mum grafiği, her zaman dilimi için açılış, en yüksek, en düşük ve kapanış fiyatını tek bir mum şeklinde gösteren fiyat grafiğidir.","trading",1],["nft","NFT (değiştirilemez token)","NFT (değiştirilemez token), her biri benzersiz bir kimliğe sahip olan ve bir dijital varlığın, koleksiyon öğesinin veya erişim hakkının blokzincir üzerindeki sahiplik kaydını temsil eden token'dır.","defi",1],["oco-order","OCO emri (biri diğerini iptal eder)","OCO emri (one-cancels-the-other), birbirine bağlı iki emirden oluşan ve biri gerçekleştiği anda diğerinin otomatik olarak iptal edildiği bir emir türüdür; genellikle kâr al ve zarar durdur emrini birlikte koymak için kullanılır.","trading",1],["phishing","Oltalama (phishing)","Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır.","wallets-security",1],["anti-phishing-code","Oltalama karşıtı kod (anti-phishing code)","Oltalama karşıtı kod, borsa hesabınızda belirlediğiniz ve borsanın size gönderdiği gerçek e-postalarda görünen kişisel bir kelimedir; bu kodu içermeyen e-postaların sahte olma ihtimali yüksektir.","wallets-security",1],["auto-deleveraging","Otomatik kaldıraç azaltma (ADL)","Otomatik kaldıraç azaltma (ADL), tasfiye edilen bir pozisyonun zararı sigorta fonuyla karşılanamadığında, borsanın karşı taraftaki kârlı ve yüksek kaldıraçlı pozisyonları otomatik olarak kısmen kapatmasıdır.","derivatives",1],["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir.","defi",1],["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur.","wallets-security",1],["p2p-trading","P2P alım satım (C2C)","P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür.","exchange-features",1],["perp-dex","Perp DEX (zincir üstü sürekli vadeli işlemler)","Perp DEX, sürekli (perpetual) vadeli kontratların kendi cüzdanınızdan, merkezi bir borsaya fon emanet etmeden, akıllı sözleşmeler veya kendi blokzinciri üzerinde işlem gördüğü merkeziyetsiz borsadır.","defi",1],["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır.","basics",1],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir.","trading",1],["market-maker","Piyasa yapıcı (Market maker)","Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir.","trading",1],["portfolio-margin","Portföy marjini (Portfolio margin)","Portföy marjini, teminat gereksinimini her pozisyon için ayrı ayrı değil, tüm portföyün toplam riskine göre hesaplayan gelişmiş bir marjin modudur.","derivatives",1],["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir.","trading",1],["referral-code","Referans kodu (komisyon iadesi)","Referans kodu, bir borsaya kaydolurken girilen ve sizi davet eden kişi veya ortakla eşleştiren; çoğu zaman işlem ücretlerinizin bir kısmının size geri ödenmesini sağlayan davet kodudur.","exchange-features",1],["restaking","Restaking (yeniden stake etme)","Restaking, zaten stake edilmiş ETH'yi veya likit staking token'larını başka hizmetlerin güvenliğini sağlamak için ikinci kez taahhüt ederek ek ödül kazanmayı amaçlayan bir yapıdır.","defi",1],["proof-of-reserves","Rezerv kanıtı (proof of reserves)","Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur.","wallets-security",1],["risk-reward-ratio","Risk-ödül oranı (Risk-reward ratio)","Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır.","trading",1],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır.","wallets-security",1],["reduce-only-order","Sadece azalt emri (Reduce-only order)","Sadece azalt emri (reduce-only), yalnızca mevcut bir pozisyonu küçültebilen ve hiçbir durumda yeni pozisyon açamayan veya mevcut pozisyonu büyütemeyen bir vadeli işlem emri seçeneğidir.","derivatives",1],["post-only-order","Sadece yapıcı (post-only) emir","Sadece yapıcı (post-only) emir, yalnızca emir defterine eklenebiliyorsa kabul edilen ve anında eşleşip taker olacaksa iptal edilen bir limit emir seçeneğidir; amacı her zaman maker ücreti ödemektir.","trading",1],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır.","wallets-security",1],["wrapped-token","Sarılmış token (wrapped token)","Sarılmış token, başka bir varlığı birebir temsil eden ve onu farklı bir blokzincirde veya farklı bir token standardında kullanılabilir hâle getiren token'dır; örneğin WBTC, Ethereum'da Bitcoin'i temsil eder.","defi",1],["satoshi","Satoshi (sats)","Satoshi (sats), Bitcoin'in en küçük birimidir; 1 BTC 100.000.000 satoshi'ye eşittir ve adını Bitcoin'in takma adlı yaratıcısı Satoshi Nakamoto'dan alır.","basics",1],["synthetic-dollar","Sentetik dolar (delta nötr stablecoin)","Sentetik dolar, spot kripto varlığı tutup aynı büyüklükte short vadeli pozisyon açarak fiyat riskini sıfırlayan ve böylece yaklaşık 1 dolar değerinde kalmayı hedefleyen token'dır.","stablecoins",1],["travel-rule","Seyahat kuralı (travel rule)","Seyahat kuralı (travel rule), kripto hizmet sağlayıcılarının belirli transferlerde gönderen ve alıcı bilgilerini birbirine iletmesini zorunlu kılan, FATF'ın 16 numaralı tavsiyesine dayanan kuraldır.","regulation",1],["short-squeeze","Short squeeze (Açık pozisyon sıkışması)","Short squeeze, fiyatın ani yükselişiyle short pozisyon sahiplerinin zararı kesmek için geri alım yapmak veya tasfiye edilmek zorunda kalması ve bu zorunlu alımların fiyatı daha da yukarı itmesidir.","derivatives",1],["hot-wallet","Sıcak cüzdan (hot wallet)","Sıcak cüzdan, özel anahtarları internete bağlı bir cihazda veya sunucuda tutulan, bu sayede hızlı işlem yapmaya uygun ama çevrim dışı saklamaya göre daha fazla saldırıya açık olan kripto cüzdanıdır.","wallets-security",1],["insurance-fund","Sigorta fonu (Insurance fund)","Sigorta fonu, vadeli işlem borsalarının tasfiye edilen pozisyonların teminatı aşan zararlarını karşılamak ve otomatik kaldıraç azaltmayı (ADL) önlemek için tuttuğu rezerv fondur.","derivatives",1],["cold-wallet","Soğuk cüzdan (cold wallet)","Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir.","wallets-security",1],["last-price","Son işlem fiyatı (Last traded price)","Son işlem fiyatı, bir borsadaki belirli bir paritede veya kontratta en son gerçekleşen alım-satım işleminin fiyatıdır.","derivatives",1],["spot-bitcoin-etf","Spot Bitcoin ETF","Spot Bitcoin ETF, gerçek bitcoin satın alıp saklayan ve borsada hisse senedi gibi işlem gören, fiyatı bitcoin'in piyasa fiyatını takip eden bir borsa yatırım fonudur.","regulation",1],["spot-trading","Spot işlem (spot trading)","Spot işlem, bir kripto parayı o anki piyasa fiyatından alıp satarak varlığın kendisine anında sahip olduğunuz, kaldıraç ve vade içermeyen temel alım satım türüdür.","trading",1],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır.","stablecoins",1],["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır.","defi",1],["stop-limit-order","Stop-limit emir","Stop-limit emir, fiyat belirlediğiniz tetik (stop) seviyesine ulaştığında, önceden tanımladığınız fiyattan bir limit emir gönderen ve böylece kötü fiyattan dolmayı engelleyen koşullu bir emirdir.","trading",1],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir.","derivatives",1],["fully-diluted-valuation","Tam seyreltilmiş değer (FDV)","Tam seyreltilmiş değer (FDV), bir token'ın güncel fiyatının maksimum veya toplam arzla çarpılmasıyla bulunan değerdir ve tüm token'lar piyasaya çıktığında projenin ne kadar büyük görüneceğini gösterir.","basics",1],["margin-call","Teminat tamamlama çağrısı (Margin call)","Teminat tamamlama çağrısı (margin call), kaldıraçlı pozisyonunuzun teminatı bakım seviyesine yaklaştığında borsanın sizi ek teminat yatırmanız veya pozisyonu küçültmeniz için uyarmasıdır.","derivatives",1],["delivery-futures","Teslimatlı vadeli kontrat (Delivery futures)","Teslimatlı vadeli kontrat, önceden belirlenmiş bir vade tarihinde kapanan ve o gün uzlaşma fiyatı üzerinden hesaplanan kripto vadeli işlem sözleşmesidir.","derivatives",1],["token-unlock","Token kilit açılımı (token unlock)","Token kilit açılımı (token unlock), ekip, yatırımcılar veya ekosistem fonu için önceden kilitlenmiş token'ların belirlenmiş bir takvime göre serbest bırakılıp alınıp satılabilir hale gelmesidir.","basics",1],["token-listing","Token listelemesi","Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır.","exchange-features",1],["token-approval","Token onayı (token approval / allowance)","Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir.","wallets-security",1],["token-burn","Token yakımı (token burn)","Token yakımı (token burn), token'ların kimsenin erişemeyeceği bir adrese gönderilerek veya kontrat tarafından imha edilerek dolaşımdan kalıcı olarak çıkarılmasıdır.","basics",1],["tokenized-gold","Tokenize altın","Tokenize altın, her biri belirli miktarda fiziki altına, genellikle bir troy onsa karşılık gelen ve bu altın bir kasada saklanan, blockchain üzerinde transfer edilebilen token'dır.","tokenized-assets",1],["tokenized-treasuries","Tokenize hazine bonoları","Tokenize hazine bonoları, ABD Hazine bonosu gibi kısa vadeli devlet borçlanma araçlarına yatırım yapan bir fonun veya yapının paylarını blockchain üzerinde token olarak temsil eden ürünlerdir.","tokenized-assets",1],["tokenized-stocks","Tokenize hisse senetleri","Tokenize hisse senetleri, bir şirketin hisse senedinin fiyatını takip eden ve genellikle bir saklayıcıda tutulan gerçek hisseyle desteklenen, blockchain üzerinde işlem gören token'lardır.","tokenized-assets",1],["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır.","basics",1],["all-time-high","Tüm zamanların en yüksek seviyesi (ATH)","Tüm zamanların en yüksek seviyesi (all-time high, ATH), bir kripto paranın işlem görmeye başladığından bu yana ulaştığı en yüksek fiyattır.","basics",1],["usdc","USDC (USD Coin)","USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir.","stablecoins",1],["usdt","USDT (Tether)","USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir.","stablecoins",1],["usdt-margined-futures","USDT teminatlı vadeli kontrat (USDT-margined futures)","USDT teminatlı vadeli kontrat, teminatın USDT olarak yatırıldığı ve kâr-zararın doğrudan USDT cinsinden, fiyat hareketiyle doğrusal olarak hesaplandığı vadeli işlem sözleşmesidir.","derivatives",1],["futures-basis","Vadeli baz (Futures basis)","Vadeli baz, bir vadeli kontratın fiyatı ile dayanak varlığın spot fiyatı arasındaki farktır ve genellikle tutar veya yıllıklandırılmış yüzde olarak ifade edilir.","derivatives",1],["futures-contract","Vadeli işlem sözleşmesi (Futures contract)","Vadeli işlem sözleşmesi, bir varlığı sahiplenmeden fiyatı üzerine işlem yapmanızı sağlayan ve iki tarafın varlığı belirli bir fiyattan ileride alıp satmayı kabul ettiği türev sözleşmedir.","derivatives",1],["validator","Validatör (doğrulayıcı)","Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür.","basics",1],["vasp","VASP (sanal varlık hizmet sağlayıcısı)","VASP (Virtual Asset Service Provider), başkaları adına kripto varlık alım satımı, takası, transferi veya saklaması yapan ve bu nedenle düzenlemeye tabi olan şirketlerdir.","regulation",1],["vip-tier","VIP ücret seviyesi","VIP ücret seviyesi, borsaların 30 günlük işlem hacminize veya hesap bakiyenize göre sizi kademelere ayırıp daha yüksek kademede daha düşük maker ve taker ücreti uyguladığı sistemdir.","exchange-features",1],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir.","basics",1],["wash-trading","Wash trading (Sahte işlem)","Wash trading, aynı kişinin veya iş birliği yapan tarafların kendi kendine alıp satarak gerçek bir talep yokken yapay işlem hacmi ve fiyat hareketi yaratmasıdır.","trading",1],["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir.","wallets-security",1],["governance-token","Yönetişim token'ı (governance token)","Yönetişim token'ı, sahiplerine bir protokolün veya DAO'nun kararlarında oy kullanma hakkı veren kripto token'ıdır; örneğin UNI, Uniswap yönetişiminde kullanılır.","defi",1],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir.","trading",1],["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir.","onchain",1],["cross-chain-bridge","Zincirler arası köprü (cross-chain bridge)","Zincirler arası köprü, bir kripto varlığı bir blokzincirden diğerine taşımanızı sağlayan ve genellikle varlığı kaynak zincirde kilitleyip hedef zincirde bir karşılığını çıkararak çalışan protokoldür.","defi",1]]});
